mapper.select:
SELECT FROM booking b JOIN member m ON m.member_id = b.member_id JOIN member_level ml ON ml.level_id = m.level_id JOIN court c ON c.court_id = b.court_id JOIN venue v ON v.venue_id = c.venue_id
AND (b.booking_no LIKE CONCAT('%', #{keyword}, '%') OR m.nickname LIKE CONCAT('%', #{keyword}, '%') OR m.phone LIKE CONCAT('%', #{keyword}, '%') OR c.court_name LIKE CONCAT('%', #{keyword}, '%'))
AND b.member_id = #{memberId}
AND b.court_id = #{courtId}
AND b.status = #{status}
AND b.start_at >= #{date} AND b.start_at < DATE_ADD(#{date}, INTERVAL 1 DAY)
ORDER BY b.start_at DESC, b.booking_id DESC

SELECT FROM booking b JOIN member m ON m.member_id = b.member_id JOIN member_level ml ON ml.level_id = m.level_id JOIN court c ON c.court_id = b.court_id JOIN venue v ON v.venue_id = c.venue_id WHERE b.member_id = #{memberId}
AND b.status = #{status}
AND b.start_at >= #{date} AND b.start_at < DATE_ADD(#{date}, INTERVAL 1 DAY)
ORDER BY b.start_at DESC, b.booking_id DESC
